const assert = require('node:assert/strict');
const { EventService } = require('../.build/service');

function fake(values, opts = {}) {
  const s = { opens: 0, reads: 0, closes: 0 };
  s.source = {
    open: async () => {
      s.opens++;
      return {
        read: async () => {
          s.reads++;
          if (opts.readFailAt === s.reads) throw new Error('read failed');
          return values.length ? values.shift() : null;
        },
        close: async () => { s.closes++; if (opts.closeFails) throw new Error('close failed'); },
      };
    },
  };
  return s;
}

async function rejects(promise, message) {
  await assert.rejects(promise, (e) => { assert.equal(e.message, message); return true; });
}

async function main() {
  // Normal exhaustion.
  {
    const s = fake(['a', 'b']);
    const found = []; for await (const v of new EventService(s.source).stream()) found.push(v);
    assert.deepEqual(found, ['A', 'B']); assert.equal(s.opens, 1); assert.equal(s.closes, 1); assert.equal(s.reads, 3);
  }
  // Lazy open, no read-ahead.
  {
    const s = fake(['a', 'b', 'c']);
    const gen = new EventService(s.source).stream();
    await Promise.resolve();
    assert.equal(s.opens, 0);
    assert.deepEqual(await gen.next(), { value: 'A', done: false }); assert.equal(s.reads, 1);
    assert.deepEqual(await gen.next(), { value: 'B', done: false }); assert.equal(s.reads, 2);
    assert.equal(s.closes, 0);
    await gen.return(undefined); assert.equal(s.closes, 1); assert.equal(s.reads, 2);
    await gen.return(undefined); assert.equal(s.closes, 1);
  }
  // Returning an unopened generator opens/closes nothing.
  {
    const s = fake(['a']);
    const gen = new EventService(s.source).stream();
    assert.deepEqual(await gen.return(undefined), { value: undefined, done: true });
    assert.deepEqual(await gen.next(), { value: undefined, done: true });
    assert.equal(s.opens, 0); assert.equal(s.closes, 0);
  }
  // Consumer break.
  {
    const s = fake(['a', 'b', 'c']);
    for await (const v of new EventService(s.source).stream()) { assert.equal(v, 'A'); break; }
    assert.equal(s.closes, 1); assert.equal(s.reads, 1);
  }
  // Break with close failure propagates close failure.
  {
    const s = fake(['a', 'b'], { closeFails: true });
    await rejects((async () => { for await (const _ of new EventService(s.source).stream()) break; })(), 'close failed');
    assert.equal(s.closes, 1);
  }
  // Exhaustion with close failure propagates close failure.
  {
    const s = fake(['a'], { closeFails: true });
    const gen = new EventService(s.source).stream();
    await gen.next();
    await rejects(gen.next(), 'close failed'); assert.equal(s.closes, 1);
  }
  // Read failure closes, original error preserved even if close fails.
  for (const closeFails of [false, true]) {
    const s = fake(['a', 'b'], { readFailAt: 2, closeFails });
    const gen = new EventService(s.source).stream();
    await gen.next();
    await rejects(gen.next(), 'read failed'); assert.equal(s.closes, 1);
    assert.deepEqual(await gen.next(), { value: undefined, done: true }); assert.equal(s.closes, 1);
  }
  // Mapper failure closes, original error preserved even if close fails.
  for (const closeFails of [false, true]) {
    const s = fake(['a', 'bad', 'c'], { closeFails });
    const mapper = (v) => { if (v === 'bad') throw new Error('mapper failed'); return v; };
    const gen = new EventService(s.source, mapper).stream();
    assert.deepEqual(await gen.next(), { value: 'a', done: false });
    await rejects(gen.next(), 'mapper failed'); assert.equal(s.closes, 1); assert.equal(s.reads, 2);
  }
  // Consumer-injected throw closes, injected error preserved even if close fails.
  for (const closeFails of [false, true]) {
    const s = fake(['a', 'b'], { closeFails });
    const gen = new EventService(s.source).stream();
    await gen.next();
    await rejects(gen.throw(new Error('injected')), 'injected'); assert.equal(s.closes, 1); assert.equal(s.reads, 1);
  }
  // Throw into unopened generator opens nothing.
  {
    const s = fake(['a']);
    const gen = new EventService(s.source).stream();
    await rejects(gen.throw(new Error('injected')), 'injected');
    assert.equal(s.opens, 0); assert.equal(s.closes, 0);
  }
  // Open failure: nothing to close.
  {
    const svc = new EventService({ open: async () => { throw new Error('open failed'); } });
    await rejects(svc.stream().next(), 'open failed');
  }
}
module.exports = main();
module.exports.catch((e) => { console.error(e); process.exitCode = 1; });

