import { Source } from './source';
import { mapEvent } from './mapper';
export class EventService {
  constructor(private readonly source: Source, private readonly mapper: (value: string) => string = mapEvent) {}
  async *stream(): AsyncGenerator<string> {
    // Generator bodies run lazily, so the lease is only opened on the first next().
    const lease = await this.source.open();
    let failed = false;
    try {
      for (;;) {
        const value = await lease.read();
        if (value === null) return;
        yield this.mapper(value);
      }
    } catch (error) {
      // Read, mapper or consumer-injected (gen.throw) failure.
      failed = true;
      throw error;
    } finally {
      if (failed) {
        // Preserve the original exception; a close failure must not mask it.
        try { await lease.close(); } catch { /* ignored in favour of original error */ }
      } else {
        // Normal exhaustion or consumer return/break: close failures propagate.
        await lease.close();
      }
    }
  }
}
